import java.util.Scanner

fun main() {
    val scanner = Scanner(System.`in`)
    val s = scanner.nextLine()
    val target = "CODEFORCES"

    var ok = false
    if (s.length >= target.length) {
        for (i in 0..target.length) {
            val prefix = target.substring(0, i)
